package com.bplus.share;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.media.MediaRecorder;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;
/** Foreground hold-to-record. Release sends, horizontal slide/cancel/lifecycle stop discards. */
public final class VoiceRecorder{
 public interface Send{void send(Uri uri,String name,long size);}
 private final Activity a;private final Send send;private MediaRecorder recorder;private File file;private long started;private float down;private boolean cancelled;private final TextView button;
 public VoiceRecorder(Activity a,TextView button,Send send){this.a=a;this.button=button;this.send=send;button.setContentDescription(a.getString(R.string.voice_hold));button.setOnTouchListener((v,e)->touch(e));}
 private boolean touch(MotionEvent e){int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){down=e.getRawX();cancelled=false;if(a.checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){new AppDialog(a).setTitle(R.string.voice_title).setMessage(R.string.voice_permission_note).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.voice_allow,(d,n)->a.requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},822)).show();return true;}start();return true;}if(action==MotionEvent.ACTION_MOVE&&recorder!=null&&VoiceRules.cancel(down,e.getRawX(),Ui.dp(a,80))){cancelled=true;button.setText(a.getString(R.string.cancel));}if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){finish(cancelled||action==MotionEvent.ACTION_CANCEL);return true;}return true;}
 private void start(){try{File dir=new File(a.getFilesDir(),"voice");if(!dir.exists()&&!dir.mkdirs())throw new IOException();file=new File(dir,"voice-"+java.util.UUID.randomUUID()+".m4a");recorder=new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setAudioSamplingRate(44100);recorder.setAudioEncodingBitRate(64000);recorder.setOutputFile(file.getAbsolutePath());recorder.setMaxDuration(300000);recorder.setOnInfoListener((r,what,extra)->{if(what==MediaRecorder.MEDIA_RECORDER_INFO_MAX_DURATION_REACHED){finish(true);Toast.makeText(a,R.string.voice_limit,1).show();}});recorder.prepare();recorder.start();started=SystemClock.elapsedRealtime();button.setText("●");button.setTextColor(0xffff6565);Toast.makeText(a,R.string.voice_recording,Toast.LENGTH_LONG).show();button.getParent().requestDisallowInterceptTouchEvent(true);}catch(Exception e){finish(true);new AppDialog(a).setTitle(R.string.voice_title).setMessage(R.string.voice_failed).setPositiveButton(android.R.string.ok,null).show();}}
 public void cancel(){finish(true);}
 private void finish(boolean discard){if(recorder==null)return;long duration=SystemClock.elapsedRealtime()-started;try{recorder.stop();}catch(Exception e){discard=true;}try{recorder.release();}catch(Exception ignored){}recorder=null;button.setText("🎙");button.setTextColor(Ui.accent);button.getParent().requestDisallowInterceptTouchEvent(false);if(file==null||!VoiceRules.send(discard,duration,file.length())){if(file!=null)file.delete();return;}Uri uri=Uri.parse("content://"+a.getPackageName()+".files/voice/"+Uri.encode(file.getName()));send.send(uri,file.getName(),file.length());}
}
